use serde_json::{Value, from_str};

pub fn solve(input: Value) -> Value {
    let jobs: Vec<Vec<i64>> = input.as_array().unwrap().iter().map(|v| v.as_array().unwrap().to_vec()).collect();
    let mut total_wait_time = 0;
    let mut current_time = 0;

    for job in jobs {
        let arrival = job[0];
        let duration = job[1];
        current_time = current_time.max(arrival) + duration;
        total_wait_time += current_time - arrival - duration;
    }

    Value::Number(total_wait_time.into())
}
